from pathlib import Path
p=Path('src/components/Header.tsx');s=p.read_text(encoding='utf-8')
s=s.replace('useEffect,useState','useEffect,useState,useRef').replace('Menu,ArrowUpRight','Menu,ArrowUpRight,ChevronDown,Leaf')
s=s.replace("const path=usePathname();", "const [mega,setMega]=useState(false);const headerRef=useRef<HTMLElement>(null);const collectionButton=useRef<HTMLButtonElement>(null);const path=usePathname();")
s=s.replace('setMenu(false);setSearch(false);','setMenu(false);setSearch(false);setMega(false);')
s=s.replace(" const matches=", " useEffect(()=>{if(!mega)return;const close=(e:PointerEvent)=>{if(!headerRef.current?.contains(e.target as Node))setMega(false);};document.addEventListener('pointerdown',close);return()=>document.removeEventListener('pointerdown',close);},[mega]);\n const matches=")
s=s.replace('<header className="site-header">','<header ref={headerRef} className="site-header" onKeyDown={e=>{if(e.key===\'Escape\'&&mega){setMega(false);collectionButton.current?.focus();}}} onBlur={e=>{if(!e.currentTarget.contains(e.relatedTarget))setMega(false);}}>')
s=s.replace('{nav.map(([label,href])=><Link aria-current={path===href?\'page\':undefined} key={href} href={href}>{label}</Link>)}','{nav.map(([label,href],i)=><div className="nav-item" key={href}><Link aria-current={path===href?\'page\':undefined} href={href}>{label}</Link>{i===0&&<button ref={collectionButton} className="collection-expand" aria-label="Explore collections" aria-expanded={mega} aria-controls="collection-menu" onClick={()=>setMega(!mega)}><ChevronDown size={14}/></button>}</div>)}')
s=s.replace('</header><Overlay','{mega&&<div id="collection-menu" className="mega-menu glass-panel"><div className="mega-intro"><Leaf size={26} strokeWidth={1}/><p className="eyebrow">FIND YOUR EVERYDAY</p><h2>A ritual.<br/>A little pause.<br/><em>Just for you.</em></h2><Link href="/shop" className="text-link" onClick={()=>setMega(false)}>Shop the whole collection</Link></div><div className="mega-collections">{collections.map((c,i)=><Link key={c.handle} href={`/collections/${c.handle}`} onClick={()=>setMega(false)}><span className="mega-image"><img src={`/images/${["jar","soap","bottle","jar"][i%4]}-render.png`} alt=""/></span><span>{c.title}</span><small>{c.description}</small></Link>)}</div></div>}</header><Overlay')
p.write_text(s,encoding='utf-8')
